import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"SSA","description":"","frontmatter":{"title":"SSA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssa-form.md","filePath":"cs/ssa-form.md","lastUpdated":1789023840000}'),c={name:"cs/ssa-form.md"};function h(_,a,A,m,f,E){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ssa" tabindex="-1">SSA <a class="header-anchor" href="#ssa" aria-label="Permalink to &quot;SSA&quot;">​</a></h1><div class="epigraph"><p>每个名字只赋值一次；汇合点用 $\\phi$ 按控制流前驱选择值。</p><footer>—— 据 Cytron et al., Efficiently Computing Static Single Assignment Form, 1991；Appel, SSA is Functional Programming, 1998 整理</footer></div><p>上一课<a href="/cs/cfg-ir">控制流图</a>允许同一变量多次赋值。数据流因此要沿 CFG 跟踪「哪一次写到达这里」。本课不重定义基本块。缺口是：<strong>静态单赋值</strong>——改名使得每次赋值一个新名，\\(\\phi\\) 处理汇合。活跃变量仍在下一课；SSA 让许多优化变成局部替换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(x\\) 被写两次，块尾读 \\(x\\) 不知道该连哪条写。到达定值分析可以回答，但每个优化都要重跑。SSA：第一次写 \\(x_1\\)，第二次 \\(x_2\\)；若两路汇合，则 \\(x_3\\leftarrow\\phi(x_1,x_2)\\)。缺口是 φ 的放置与改名，不是新的 ISA。</p><p>支配边界决定 φ 插在哪：在「有的前驱带来这个定值、有的没有」的入口。Cytron 等给出与支配树相关的高效放置。本课要直觉，不证长度。</p><h3 id="φ-不是运行时指令" tabindex="-1">φ 不是运行时指令 <a class="header-anchor" href="#φ-不是运行时指令" aria-label="Permalink to &quot;φ 不是运行时指令&quot;">​</a></h3><p>φ 在块首语义上「按来边选」。后端必须拆成各前驱块末的传送，或与寄存器分配合并。不要把 φ 发给<a href="/cs/riscv-int-isa">RISC-V</a>。</p><p><span class="marginnote">Cytron et al. 1991。Appel 指出 SSA 与函数式 let 的对应。剪枝 SSA、半剪枝决定哪些名字需要 φ。本课默认剪枝：只用会再被读的名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算支配树。对每个赋值的名字，在支配边界插 φ，再按支配序改名。化简：常数、拷贝，\\(x_2\\leftarrow x_1\\) 可替换。</p>',11)),(e(),n(S,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%20%2B%20%E5%A4%9A%E6%AC%A1%E8%B5%8B%E5%80%BC%22%5D%20--%3E%20PHI%5B%22%E6%94%AF%E9%85%8D%E8%BE%B9%E7%95%8C%E6%8F%92%20%CF%86%22%5D%0A%20%20PHI%20--%3E%20RNM%5B%22%E6%94%B9%E5%90%8D%E6%88%90%E5%8D%95%E8%B5%8B%E5%80%BC%22%5D%0A%20%20RNM%20--%3E%20OPT%5B%22%E6%9B%BF%E6%8D%A2%E4%B8%8E%E5%8C%96%E7%AE%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/dfs-edge-types">图算法</a>：支配用 DFS 深度与半支配（Lengauer–Tarjan）可算，本课点名算法名，不展开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>死代码：赋值结果从未被读则可删（φ 的操作数也要跟着收）。常数传播在 SSA 上是替换。寄存器分配前通常离开 SSA（拆 φ）。本课不着色。</p><p>不可约 CFG 仍可 SSA，φ 更多。不要要求所有程序先变成循环树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算活跃变量方程、不选指令。不把 memory SSA 写完（别名使内存不是标量名）。后课默认：标量 IR 可在 SSA 上优化。数据流方程以活跃变量为代表下一课补。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SSA：一次赋值一名；汇合用 φ。</li><li>φ 按支配边界放置，后端要拆掉。</li><li>优化变成改名与替换。</li><li>出处：Cytron et al., 1991；Appel, 1998。</li></ul>',8))])}const C=s(c,[["render",h]]);export{x as __pageData,C as default};
